CREATE UNIQUE INDEX UX_c09_purchase_invoice ON dbo.test_current_price_purchase_intents(invoice_id) WHERE invoice_id IS NOT NULL;
CREATE TABLE dbo.test_current_price_purchase_requests(request_id uniqueidentifier NOT NULL PRIMARY KEY,actor_id bigint NOT NULL,operation nvarchar(30) NOT NULL,payload_json nvarchar(max) NOT NULL,payload_hash char(64) NOT NULL,entity_id bigint NOT NULL,response_json nvarchar(max) NOT NULL,created_at datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT CK_c09_purchase_request CHECK(actor_id=16 AND entity_id>0 AND ISJSON(payload_json)=1 AND ISJSON(response_json)=1 AND operation IN(N'quote_create',N'receipt_accept',N'receipt_reject',N'draft_create',N'draft_finalize',N'draft_cancel')));
