,4) AND EXISTS(SELECT 1 FROM dbo.test_daily_drafts g WHERE g.id=t.receipt_id AND g.state=N''approved'' AND g.decided_by=16 AND g.flow=N''purchase'' AND g.kind=N''goods'' AND g.created_by=16 AND ISJSON(g.payload_json)=1 AND JSON_VALUE(g.payload_json,''$.marker'')=N''C09PRICE'' AND TRY_CONVERT(bigint,JSON_VALUE(g.payload_json,''$.intentId''))=t.id AND TRY_CONVERT(decimal(18,3),JSON_VALUE(g.payload_json,''$.quantity''))=t.quantity AND JSON_VALUE(g.payload_json,''$.unit'')=N''ADET'' AND TRY_CONVERT(decimal(28,8),JSON_VALUE(g.payload_json,''$.unitFactor''))=1 AND JSON_VALUE(g.payload_json,''$.warehouse'')=N''TEST-DAILY-WH'' AND TRY_CONVERT(date,JSON_VALUE(g.payload_json,''$.date''))=t.document_date AND TRY_CONVERT(decimal(18,4),JSON_VALUE(g.payload_json,''$.unitCostTry''))=ROUND(t.amount_try/t.quantity,4) AND TRY_CONVERT(decimal(18,4),JSON_VALUE(g.payload_json,''$.amountTry''))=t.amount_try) AND(SELECT COUNT(*) FROM dbo.stock_movements m WHERE m.source_type=N''goods_receipt'' AND m.source_id=t.receipt_id AND m.product_id=301986)=1 AND EXISTS(SELECT 1 FROM dbo.stock_movements m WHERE m.product_id=301986 AND m.source_type=N''goods_receipt'' AND m.source_id=t.receipt_id AND m.movement_type=N''in'' AND m.quantity_in=t.quantity AND m.quantity_out=0 AND m.quantity_net=t.quantity AND m.unit_cost_try=ROUND(t.amount_try/t.quantity,4) AND m.unit_price=ROUND(t.amount_try/t.quantity,4) AND m.average_cost_try_after=t.cost_after AND m.amount_try=t.amount_try AND m.currency_code=N''TRY'' AND m.document_date=t.document_date AND m.supplier_id=13373 AND m.created_by=16 AND m.warehouse_name=N''TEST-DAILY-WH'' AND m.source_warehouse=N''TEST-DAILY-WH'' AND m.source_record_key IS NULL AND m.migration_run_id IS NULL) AND h.supplier_id=13373 AND h.supplier_currency=N''TRY'' AND h.document_no=t.document_no AND h.document_date=t.document_date AND h.document_currency=t.currency AND h.exchange_rate_snapshot=t.document_rate AND h.subtotal=t.document_total AND h.grand_total=t.document_total AND h.amo