_date=t.document_date AND m.source_record_key IS NULL AND m.migration_run_id IS NULL AND m.invoice_return_id IS NULL AND m.balance_effect_exact IS NULL AND(m.affects_balance IS NULL OR m.affects_balance=1) AND((m.movement_type=N''purchase_invoice'' AND h.status=N''draft'' AND m.created_by IS NULL AND(m.balance_effect=t.document_total OR m.balance_effect=t.account_total)) OR(m.movement_type=N''purchase_invoice_cancel'' AND h.status=N''finalized'' AND m.created_by=16 AND(m.balance_effect=-t.document_total OR m.balance_effect=-t.account_total))) AND(m.account_currency IS NULL OR m.account_currency=N''TRY'') AND(m.account_amount IS NULL OR m.account_amount=t.account_total) AND(m.document_exchange_rate_snapshot IS NULL OR m.document_exchange_rate_snapshot=t.document_rate) AND(m.account_exchange_rate_snapshot IS NULL OR m.account_exchange_rate_snapshot=1) AND(m.amount_try IS NULL OR m.amount_try=t.amount_try)) OR(SELECT COUNT(*) FROM dbo.supplier_movements z WHERE z.purchase_invoice_id=t.invoice_id AND z.movement_type=m.movement_type)<>1) THROW 51097,''C09_CURRENT_PRICE_LINEAGE_REQUIRED'',1;
