IF NOT EXISTS(SELECT 1 FROM inserted r JOIN dbo.test_current_price_purchase_intents t ON t.receipt_id=r.entity_id OR t.invoice_id=r.entity_id WHERE r.actor_id=16 AND ISJSON(r.payload_json)=1 AND ISJSON(r.response_json)=1 AND r.payload_hash=CONVERT(char(64),HASHBYTES(''SHA2_256'',r.payload_json),2) AND JSON_VALUE(r.payload_json,''$.operation'')=r.operation AND JSON_VALUE(r.payload_json,''$.input.requestId'')=LOWER(CONVERT(nvarchar(36),r.request_id)) AND TRY_CONVERT(bigint,JSON_VALUE(r.response_json,''$.id''))=r.entity_id AND TRY_CONVERT(bigint,JSON_VALUE(r.response_json,''$.intentId''))=t.id AND TRY_CONVERT(bigint,JSON_VALUE(r.response_json,''$.receiptId''))=t.receipt_id AND JSON_VALUE(r.response_json,''$.previewHash'')=t.payload_hash AND JSON_VALUE(r.response_json,''$.priceExact'')=CONVERT(varchar(100),t.price_exact) AND JSON_VALUE(r.response_json,''$.nativePriceExact4'')=CONVERT(varchar(100),t.native_price) AND JSON_VALUE(r.response_json,''$.documentAmountExact4'')=CONVERT(varchar(100),t.document_total) AND JSON_VALUE(r.response_json,''$.accountAmountExact4'')=CONVERT(varchar(100),t.account_total) AND JSON_VALUE(r.response_json,''$.amountTryExact4'')=CONVERT(varchar(100),t.amount_try) AND JSON_VALUE(r.response_json,''$.sourceProof.priceId'')=CONVERT(varchar(20),t.native_price_id) AND JSON_VALUE(r.response_json,''$.sourceProof.versionId'')=CONVERT(varchar(20),t.version_id) AND JSON_VALUE(r.response_json,''$.sourceProof.revision'')=t.before_revision AND((r.operation=N''quote_create'' AND r.entity_id=t.receipt_id AND t.status=N''quoted'' AND t.request_id=r.request_id) OR(r.operation=N''receipt_accept'' AND r.entity_id=t.receipt_id AND t.status=N''received'' AND t.stock_before IS NOT NULL AND t.cost_before IS NOT NULL AND t.stock_after IS NOT NULL AND t.cost_after IS NOT NULL AND t.stock_before>=0 AND t.stock_after=t.stock_before+t.quantity AND t.stock_after<=40 AND t.cost_before>0 AND t.cost_after>0 AND t.cost_after<=200 AND t.cost_after=ROUND((t.stock_before*t.cost_before+t.amount_try)/t.stock_after,4) AND EXISTS(SELECT 1 FROM dbo.test_daily_drafts g WHERE g.id=t.receipt_id AND g.state=N''approved'' AND g.decided_by=16 AND g.flow=N''purchase'' AND g.kind=N''goods'' AND g.created_by=16 AND ISJSON(g.payload_json)=1 AND JSON_VALUE(g.payload_json,''$.marker'')=N''C09PRICE'' AND TRY_CONVERT(bigint,JSON_VALUE(g.payload_json,''$.intentId''))=t.id AND TRY_CONVERT(decimal(18,3),JSON_VALUE(g.payload_json,''$.quantity''))=t.quantity AND JSON_VALUE(g.payload_json,''$.unit'')=N''ADET'' AND TRY_CONVERT(decimal(28,8),JSON_VALUE(g.payload_json,''$.unitFactor''))=1 AND JSON_VALUE(g.payload_json,''$.warehouse'')=N''TEST-DAILY-WH'' AND TRY_CONVERT(date,JSON_VALUE(g.payload_json,''$.date''))=t.document_date AND TRY_CONVERT(decimal(18,4),JSON_VALUE(g.payload_json,''$.unitCostTry''))=ROUND(t.amount_try/t.quantity,4) AND TRY_CONVERT(decimal(18,4),JSON_VALUE(g.payload_json,''$.amountTry''))=t.amount_try) AND(SELECT COUNT(*) FROM dbo.stock_movements m WHERE m.source_type=N''goods_receipt'' AND m.source_id=t.receipt_id AND m.product_id=301986)=1 AND EXISTS(SELECT 1 FROM dbo.stock_movements m WHERE m.product_id=301986 AND m.source_type=N''goods_receipt'' AND m.source_id=t.receipt_id AND m.movement_type=N''in'' AND m.quantity_in=t.quantity AND m.quantity_out=0 AND m.quantity_net=t.quantity AND m.unit_cost_try=ROUND(t.amount_try/t.quantity,4) AND m.unit_price=ROUND(t.amount_try/t.quantity,4) AND m.average_cost_try_after=t.cost_after AND m.amount_try=t.amount_try AND m.currency_code=N''TRY'' AND m.document_date=t.document_date AND m.supplier_id=13373 AND m.created_by=16 AND m.warehouse_name=N''TEST-DAILY-WH'' AND m.source_warehouse=N''TEST-DAILY-WH'' AND m.source_record_key IS NULL AND m.migration_run_id IS NULL)) OR(r.operation=N''receipt_reject'' AND r.entity_id=t.receipt_id AND t.status=N''rejected'') OR(r.operation=N''draft_create'' AND r.entity_id=t.invoice_id AND t.status=N''linked'' AND EXISTS(SELECT 1 FROM dbo.purchase_invoices nh WHERE nh.id=t.invoice_id AND nh.supplier_id=13373 AND nh.supplier_currency=N''TRY'' AND nh.document_no=t.document_no AND nh.document_date=t.document_date AND nh.document_currency=t.currency AND nh.exchange_rate_snapshot=t.document_rate AND nh.subtotal=t.document_total AND nh.grand_total=t.document_total AND nh.amount_try=t.amount_try AND nh.stock_cost_effect_try=t.amount_try AND nh.line_discount_total=0 AND nh.invoice_discount_rate=0 AND nh.supplier_discount_rate=0 AND nh.discount_total=0 AND nh.invoice_discount_type=N''rate'' AND nh.invoice_discount_amount=0 AND(nh.created_by IS NULL OR nh.created_by=16) AND(nh.updated_by IS NULL OR nh.updated_by=16) AND nh.is_migrated=0 AND nh.affects_inventory=1 AND nh.source_system IS NULL AND nh.source_record_key IS NULL AND nh.migration_run_id IS NULL AND nh.inventory_cutover_id IS NULL) AND(SELECT COUNT(*) FROM dbo.purchase_invoice_items WHERE purchase_invoice_id=t.invoice_id)=1 AND EXISTS(SELECT 1 FROM dbo.purchase_invoice_items ni WHERE ni.purchase_invoice_id=t.invoice_id AND ni.product_id=301986 AND ni.stock_code_snapshot=N''TEST-DAILY-PURCHASE'' AND ni.product_name_snapshot=(SELECT name FROM dbo.products WHERE id=301986) AND ni.quantity=t.quantity AND ni.purchase_price=t.native_price AND ni.currency_code=t.currency AND ni.line_discount_rate=0 AND ni.line_total=t.document_total AND ni.line_total_try=t.amount_try AND ni.stock_effect_snapshot=N''goods_receipt_already_posted'' AND ni.source_record_key IS NULL AND ni.migration_run_id IS NULL) AND NOT EXISTS(SELECT 1 FROM dbo.stock_movements WHERE source_type=N''purchase_invoice'' AND source_id=t.invoice_id)) OR(r.operation=N''draft_finalize'' AND r.entity_id=t.invoice_id AND t.status=N''linked'' AND EXISTS(SELECT 1 FROM dbo.purchase_invoices h WHERE h.id=t.invoice_id AND h.status=N''finalized'')) OR(r.operation=N''draft_cancel'' AND r.entity_id=t.invoice_id AND t.status=N''cancelled''))) THROW 51097,''C09_CURRENT_PRICE_LINEAGE_REQUIRED'',1;
